using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF Core 8 discriminator property name so existing documents
            // (which store "Discriminator": "Product") remain queryable.
            // EF Core 9 default changed to "$type".
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF Core 8 compound id format ("Product|123") so existing
            // documents remain accessible via FindAsync/point-reads.
            // EF Core 9 default changed to key-only id ("123").
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // REMOVED: HasIndex is no longer silently ignored — it throws in EF Core 9.
        // Cosmos DB indexing is managed via the container's indexing policy.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

